import type { Metadata } from "next";
import { site } from "@/data/site";

type PageMetadataInput = {
  /** Page title; the root layout's template appends the site name. */
  title: string;
  description: string;
  /** Route path, e.g. "/about". Used for canonical and Open Graph URLs. */
  path: string;
};

/** The share image generated by src/app/opengraph-image.tsx. */
const shareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${site.name}, ${site.role}`,
};

/**
 * Per-page metadata. A child `openGraph` (or `twitter`) object replaces the root one
 * entirely, including the file-based share image, so shared fields and the image are
 * repeated here.
 */
export function pageMetadata({ title, description, path }: PageMetadataInput): Metadata {
  const fullTitle = `${title} | ${site.name}`;

  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_GB",
      siteName: site.name,
      url: path,
      title: fullTitle,
      description,
      images: [shareImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [shareImage],
    },
  };
}
